import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId?: string;
  sessionId?: string;
  workspaceId?: string;
  authHeaders?: Record<string, string>;
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

interface RegisteredTool {
  definition: ToolDefinitionSource;
  executor: ToolExecutor;
  promptInstructions?: string;
  validator?: ValidateFunction;
}

const ajv = new Ajv({
  allErrors: true,
  format: false,
  unknownFormats: 'ignore',
  strictKeywords: false,
  strictDefaults: false,
  coerceTypes: false,
  useDefaults: false,
  addUsedSchema: false,
  logger: false,
});

export function normalizeToolResponse(raw: string | ToolResponse): ToolResponse {
  if (typeof raw === 'string') return {result: raw};
  return raw;
}

export class ToolRegistry {
  private tools = new Map<string, RegisteredTool>();
  private dynamicValidators = new WeakMap<ToolDefinition['inputSchema'], ValidateFunction>();

  register(definition: ToolDefinitionSource, executor: ToolExecutor, promptInstructions?: string): void {
    if (typeof definition === 'function') {
      const name = definition().name;
      this.tools.set(name, {definition, executor, promptInstructions});
      return;
    }

    const validator = compileInputSchema(definition.name, definition.inputSchema);
    this.tools.set(definition.name, {definition, executor, promptInstructions, validator});
  }

  getDefinitions(): ToolDefinition[] {
    return Array.from(this.tools.values()).map(t => (typeof t.definition === 'function' ? t.definition() : t.definition));
  }

  getPromptInstructions(): string[] {
    return Array.from(this.tools.values())
      .map(t => t.promptInstructions)
      .filter((inst): inst is string => inst !== undefined);
  }

  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) throw new Error(`Unknown tool: ${name}`);
    this.resolveValidator(name, tool);
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const raw = await tool.executor(input, context);
    const response = normalizeToolResponse(raw);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof raw,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private resolveValidator(name: string, tool: RegisteredTool): ValidateFunction {
    if (tool.validator) return tool.validator;
    const schema = (typeof tool.definition === 'function' ? tool.definition() : tool.definition).inputSchema;
    const cached = this.dynamicValidators.get(schema);
    if (cached) return cached;
    const compiled = compileInputSchema(name, schema);
    this.dynamicValidators.set(schema, compiled);
    return compiled;
  }
}

function compileInputSchema(toolName: string, schema: ToolDefinition['inputSchema']): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${detail}`);
  }
}

